// FR10 (field minimization): only subject + a truncated plain-text body ever
// leave this workflow toward LLM Gateway / Gemini -- never raw_payload or
// headers, which are not even part of this workflow's input in the first
// place (Execute Workflow Trigger only declares email_id/subject/body).
const input = $json || {};
const emailId = input.email_id;

// Malformed input (null/missing subject or body) must never throw here (AC2).
const subject = input.subject === null || input.subject === undefined ? '' : String(input.subject);
const bodyRaw = input.body === null || input.body === undefined ? '' : String(input.body);
const truncatedBody = bodyRaw.slice(0, 2000);

const systemPrompt = 'You are an email triage assistant. Read the email and classify it, then produce a one-line summary. Respond only with JSON matching the given schema. Also classify the email\'s platform, priority, tone, and extract any relevant entities, all inferred only from the subject and body given -- never invent facts not present in the text.';
const userContent = `Subject: ${subject}\n\nBody:\n${truncatedBody}`;

// Mirrors the response_schema shape pinned as the example in llm-gateway.json's pinData.
// FR3 (009-dashboard-messages-api): category/summary keep their exact prior wording and
// schema position; platform/confidence/priority/priority_score/reasons/tone/tone_evidence/
// tldr/entities are new fields requested alongside them.
const responseSchema = {
  type: 'object',
  properties: {
    category: {
      type: 'string',
      enum: [
        'needs_reply',
        'fyi',
        'waiting_on_someone_else',
        'promotional',
        'low_priority',
      ],
    },
    summary: {
      type: 'string',
    },
    platform: {
      type: 'string',
      enum: [
        'needs-reply',
        'meeting',
        'invoice',
        'fyi',
        'newsletter',
        'automated',
        'spam-ish',
      ],
    },
    confidence: {
      type: 'integer',
    },
    priority: {
      type: 'string',
      enum: ['urgent', 'normal', 'low'],
    },
    priority_score: {
      type: 'integer',
    },
    reasons: {
      type: 'array',
      items: {
        type: 'string',
      },
    },
    tone: {
      type: 'string',
      enum: ['tense', 'neutral', 'warm'],
    },
    tone_evidence: {
      type: 'string',
      nullable: true,
    },
    tldr: {
      type: 'string',
      nullable: true,
    },
    entities: {
      type: 'object',
      properties: {
        dates: { type: 'array', items: { type: 'string' } },
        amounts: { type: 'array', items: { type: 'string' } },
        people: { type: 'array', items: { type: 'string' } },
        links: { type: 'array', items: { type: 'string' } },
        addresses: { type: 'array', items: { type: 'string' } },
      },
    },
  },
  required: [
    'category',
    'summary',
    'platform',
    'confidence',
    'priority',
    'priority_score',
    'reasons',
    'tone',
    'entities',
  ],
};

return {
  json: {
    email_id: emailId,
    system_prompt: systemPrompt,
    user_content: userContent,
    response_schema: responseSchema,
  },
};

// Never throws unhandled (Working Rule: no unhandled exception leaves this
// workflow) -- any unexpected error still produces a { ok: false, error }
// item that routes to the failure-write branch.
try {
  const gatewayResult = $json || {};
  let emailId;
  try {
    emailId = $('Build triage prompt').item.json.email_id;
  } catch (refErr) {
    emailId = null;
  }

  if (!gatewayResult.success) {
    const message = gatewayResult.error || 'LLM Gateway call failed';
    return { json: { ok: false, email_id: emailId, error: String(message) } };
  }

  const data = gatewayResult.data || {};
  const category = data.category;
  const summary = data.summary;

  // FR5 -- defense in depth against the model's own (untrusted) output. The
  // DB CHECK constraint (0002_triage_schema.sql) is the enforced boundary;
  // this check exists to produce a clean application-level error instead of
  // a raw SQL constraint violation.
  const ALLOWED_CATEGORIES = [
    'needs_reply',
    'fyi',
    'waiting_on_someone_else',
    'promotional',
    'low_priority',
  ];
  if (typeof category !== 'string' || !ALLOWED_CATEGORIES.includes(category)) {
    return { json: { ok: false, email_id: emailId, error: `invalid category: ${category}` } };
  }

  // FR9 -- summary shape guard: no newlines, no URLs, no control characters, <= 160 chars.
  if (typeof summary !== 'string') {
    return {
      json: {
        ok: false,
        email_id: emailId,
        error: 'summary failed shape validation: not a string',
      },
    };
  }

  const summaryShapeReasons = [];
  if (/[\r\n]/.test(summary)) summaryShapeReasons.push('contains a newline');
  if (/https?:\/\//i.test(summary)) summaryShapeReasons.push('contains a URL');
  // eslint-disable-next-line no-control-regex
  if (/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/.test(summary)) summaryShapeReasons.push('contains control characters');
  if (summary.length > 160) summaryShapeReasons.push(`exceeds 160 characters (${summary.length})`);

  if (summaryShapeReasons.length > 0) {
    return {
      json: {
        ok: false,
        email_id: emailId,
        error: `summary failed shape validation: ${summaryShapeReasons.join(', ')}`,
      },
    };
  }

  // FR4 (009-dashboard-messages-api) -- equivalent shape checks for every new
  // field. Any single field failing validation fails the whole result, same
  // defense-in-depth posture as the category/summary checks above: this is
  // one LLM call producing one coherent record, not independently-gradeable
  // fields.
  const ALLOWED_PLATFORMS = [
    'needs-reply',
    'meeting',
    'invoice',
    'fyi',
    'newsletter',
    'automated',
    'spam-ish',
  ];
  const platform = data.platform;
  if (typeof platform !== 'string' || !ALLOWED_PLATFORMS.includes(platform)) {
    return { json: { ok: false, email_id: emailId, error: `invalid platform: ${platform}` } };
  }

  const confidence = data.confidence;
  if (!Number.isInteger(confidence) || confidence < 0 || confidence > 100) {
    return { json: { ok: false, email_id: emailId, error: `invalid confidence: ${confidence}` } };
  }

  const ALLOWED_PRIORITIES = ['urgent', 'normal', 'low'];
  const priority = data.priority;
  if (typeof priority !== 'string' || !ALLOWED_PRIORITIES.includes(priority)) {
    return { json: { ok: false, email_id: emailId, error: `invalid priority: ${priority}` } };
  }

  const priorityScore = data.priority_score;
  if (!Number.isInteger(priorityScore) || priorityScore < 0 || priorityScore > 100) {
    return { json: { ok: false, email_id: emailId, error: `invalid priority_score: ${priorityScore}` } };
  }

  const reasons = data.reasons;
  if (!Array.isArray(reasons) || !reasons.every((r) => typeof r === 'string')) {
    return { json: { ok: false, email_id: emailId, error: 'reasons must be an array of strings' } };
  }

  const ALLOWED_TONES = ['tense', 'neutral', 'warm'];
  const tone = data.tone;
  if (typeof tone !== 'string' || !ALLOWED_TONES.includes(tone)) {
    return { json: { ok: false, email_id: emailId, error: `invalid tone: ${tone}` } };
  }

  const toneEvidence = data.tone_evidence === undefined ? null : data.tone_evidence;
  if (toneEvidence !== null && typeof toneEvidence !== 'string') {
    return { json: { ok: false, email_id: emailId, error: 'tone_evidence must be a string or null' } };
  }

  const tldr = data.tldr === undefined ? null : data.tldr;
  if (tldr !== null && typeof tldr !== 'string') {
    return { json: { ok: false, email_id: emailId, error: 'tldr must be a string or null' } };
  }

  // entities.* are arrays; a missing sub-key defaults to [] rather than
  // failing validation -- an email genuinely without any dates/amounts/etc.
  // is the common case, not an error.
  const rawEntities = data.entities && typeof data.entities === 'object' ? data.entities : {};
  const ENTITY_KEYS = ['dates', 'amounts', 'people', 'links', 'addresses'];
  const entities = {};
  for (const key of ENTITY_KEYS) {
    const value = rawEntities[key];
    if (value === undefined) {
      entities[key] = [];
    } else if (Array.isArray(value)) {
      entities[key] = value;
    } else {
      return { json: { ok: false, email_id: emailId, error: `entities.${key} must be an array` } };
    }
  }

  return {
    json: {
      ok: true,
      email_id: emailId,
      category,
      summary,
      platform,
      confidence,
      priority,
      priority_score: priorityScore,
      reasons,
      tone,
      tone_evidence: toneEvidence,
      tldr,
      entities,
    },
  };
} catch (err) {
  let emailId = null;
  try {
    emailId = $('Build triage prompt').item.json.email_id;
  } catch (refErr) {
    emailId = null;
  }
  return {
    json: {
      ok: false,
      email_id: emailId,
      error: (err && err.message) || 'Unknown Triage Pipeline error',
    },
  };
}

// .first() rather than .item: with multiple items in flight (e.g. running
// this workflow against more than one pinned fixture item at once during
// testing), .item cannot resolve a single unambiguous upstream match and
// n8n throws 'Multiple matches' -- confirmed live during 004-triage AC
// testing. .first() is safe here regardless of item count since each
// invocation of this whole sub-workflow (from Email Normaliser) always
// carries exactly one email through it in production.
const emailId = $('Validate triage result').first().json.email_id;
return { json: { email_id: emailId, triaged: true } };

// .first() rather than .item -- see 'Format success output' node's note:
// .item cannot resolve a single unambiguous upstream match when multiple
// items are in flight, confirmed live during 004-triage AC testing.
const emailId = $('Validate triage result').first().json.email_id;
return { json: { email_id: emailId, triaged: false } };
